const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Členy</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nemecký člen sa nie vždy zhoduje so slovenským rodom. Preto je najlepšie učiť sa podstatné mená spolu s členom.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Príklady členov</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — stôl</div>\n      <div class=\"kurss-example\">die Tür — dvere</div>\n      <div class=\"kurss-example\">das Messer — nôž</div>\n      <div class=\"kurss-example\">das Mädchen — dievča</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Často DER</h4>\n    <p class=\"artikuli-explain\">DER majú často osoby mužského rodu, dni, mesiace, ročné obdobia a niektoré slová s určitými príponami.</p>\n\n    <h5 class=\"artikuli-subtitle\">Pravidlá</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → často DER, napríklad: der Computer, der Lehrer <span class=\"artikuli-note\">ale nie vždy</span></div>\n      <div class=\"kurss-example\">-ling → často DER, napríklad: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → často DER, napríklad: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">osoby mužského rodu → der Mann, der Vater</div>\n      <div class=\"kurss-example\">povolania → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">značky automobilov → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">dni → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">mesiace → der August, der Dezember</div>\n      <div class=\"kurss-example\">ročné obdobia → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Príklady</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — muž</div>\n      <div class=\"kurss-example\">der Vater — otec</div>\n      <div class=\"kurss-example\">der Montag — pondelok</div>\n      <div class=\"kurss-example\">der August — august</div>\n      <div class=\"kurss-example\">der Sommer — leto</div>\n      <div class=\"kurss-example\">der Lehrer — učiteľ</div>\n      <div class=\"kurss-example\">der Computer — počítač</div>\n      <div class=\"kurss-example\">der Schmetterling — motýľ</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Často DIE</h4>\n    <p class=\"artikuli-explain\">DIE majú často osoby ženského rodu, množné číslo a slová s príponami -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Pravidlá</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">osoby ženského rodu → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">značky motocyklov → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">množné číslo → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">množné číslo takmer vždy → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Príklady</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — žena</div>\n      <div class=\"kurss-example\">die Mutter — matka</div>\n      <div class=\"kurss-example\">die Wohnung — byt</div>\n      <div class=\"kurss-example\">die Rechnung — účet</div>\n      <div class=\"kurss-example\">die Freiheit — sloboda</div>\n      <div class=\"kurss-example\">die Möglichkeit — možnosť</div>\n      <div class=\"kurss-example\">die Mannschaft — tím / mužstvo</div>\n      <div class=\"kurss-example\">die Nation — národ</div>\n      <div class=\"kurss-example\">die Universität — univerzita</div>\n      <div class=\"kurss-example\">die Polizei — polícia</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Často DAS</h4>\n    <p class=\"artikuli-explain\">DAS majú často zdrobneniny na -chen / -lein, mnohé slová na -ment / -um a slovesá použité ako podstatné mená.</p>\n\n    <h5 class=\"artikuli-subtitle\">Pravidlá</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">kovy → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">chemické prvky → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hotely → das Hotel</div>\n      <div class=\"kurss-example\">farby ako podstatné mená → das Rot, das Blau</div>\n      <div class=\"kurss-example\">sloveso ako podstatné meno → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">slovesá ako podstatné mená → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Príklady</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — dieťa</div>\n      <div class=\"kurss-example\">das Mädchen — dievča</div>\n      <div class=\"kurss-example\">das Häuschen — domček</div>\n      <div class=\"kurss-example\">das Instrument — nástroj</div>\n      <div class=\"kurss-example\">das Zentrum — centrum</div>\n      <div class=\"kurss-example\">das Museum — múzeum</div>\n      <div class=\"kurss-example\">das Essen — jedenie / jedlo</div>\n      <div class=\"kurss-example\">das Lernen — učenie sa</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Dôležité výnimky / treba sa naučiť s členom</h4>\n    <p class=\"artikuli-explain\">Pri niektorých slovách sa člen nedá spoľahlivo určiť podľa prípony ani podľa slovenského rodu. Tieto slová je najlepšie učiť sa spolu s členom.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — dvere</div>\n      <div class=\"kurss-example\">das Messer — nôž</div>\n      <div class=\"kurss-example\">die Sonne — slnko</div>\n      <div class=\"kurss-example\">der Mond — mesiac</div>\n      <div class=\"kurss-example\">das Mädchen — dievča</div>\n      <div class=\"kurss-example\">das Auto — auto</div>\n      <div class=\"kurss-example\">der Käse — syr</div>\n      <div class=\"kurss-example\">die Gabel — vidlička</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Prípony a skupiny slov pomáhajú odhadnúť člen, ale nie sú 100% spoľahlivým pravidlom. Ak si nie si istý, uč sa slovo spolu s členom.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Zámená</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ a Dativ — tvary zámen.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — kto? čo?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — ja</div><div class=\"kurss-example\">du — ty</div><div class=\"kurss-example\">er — on</div><div class=\"kurss-example\">sie — ona</div><div class=\"kurss-example\">es — ono</div><div class=\"kurss-example\">wir — my</div><div class=\"kurss-example\">ihr — vy</div><div class=\"kurss-example\">sie — oni / ony</div><div class=\"kurss-example\">Sie — Vy (zdvorilostne)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — koho? čo?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mňa</div><div class=\"kurss-example\">dich — teba</div><div class=\"kurss-example\">ihn — jeho (m. r.)</div><div class=\"kurss-example\">sie — ju (ž. r.)</div><div class=\"kurss-example\">es — ho</div><div class=\"kurss-example\">uns — nás</div><div class=\"kurss-example\">euch — vás</div><div class=\"kurss-example\">sie — ich</div><div class=\"kurss-example\">Sie — Vás (zdvorilostne)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — komu? čomu?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — mne</div><div class=\"kurss-example\">dir — tebe</div><div class=\"kurss-example\">ihm — jemu</div><div class=\"kurss-example\">ihr — jej</div><div class=\"kurss-example\">uns — nám</div><div class=\"kurss-example\">euch — vám</div><div class=\"kurss-example\">ihnen — im</div><div class=\"kurss-example\">Ihnen — Vám (zdvorilostne)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Ako vybrať tvar?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — podmet (kto koná?)</li><li><span class=\"case-red\">Akkusativ</span> — priamy predmet (koho? čo?)</li><li><span class=\"case-green\">Dativ</span> — nepriamy predmet (komu? čomu?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Príklady</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Vidím ťa.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Vidím ho.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Máme vás radi.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Pomáham ti.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Dávam mu knihu.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Ďakujeme vám.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ je vždy podmet vety, zatiaľ čo Akkusativ a Dativ sú predmety. Pozri sa na sloveso a pýtaj sa: <span class=\"case-red\">koho? čo?</span> alebo <span class=\"case-green\">komu? čomu?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Samohlásky — dlhé a krátke</h3>\n            <p class=\"kurss-lesson-intro\">V nemčine môžu byť samohlásky dlhé alebo krátke. To ovplyvňuje výslovnosť slova.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dlhá samohláska</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — teplý</div><div class=\"kurss-example\">gut (gút) — dobrý</div><div class=\"kurss-example\">Tat (tát) — čin / skutok</div><div class=\"kurss-example\">Flur (flúr) — chodba</div><div class=\"kurss-example\">Weg (vék) — cesta</div><div class=\"kurss-example\">Hut (hút) — klobúk</div><div class=\"kurss-example\">Hof (hóf) — dvor</div><div class=\"kurss-example\">Schlaf (šláf) — spánok</div></div>\n              <p>Ak za samohláskou nasleduje jedna spoluhláska, samohláska sa často vyslovuje dlho.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Krátka samohláska</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilc) — huba</div><div class=\"kurss-example\">Wort (vort) — slovo</div><div class=\"kurss-example\">Mund (munt) — ústa</div><div class=\"kurss-example\">bald (balt) — čoskoro</div><div class=\"kurss-example\">scharf (šarf) — ostrý</div><div class=\"kurss-example\">Feld (felt) — pole</div><div class=\"kurss-example\">voll (fol) — plný</div></div>\n              <p>Ak za samohláskou nasledujú dve alebo viac spoluhlások, samohláska sa často vyslovuje krátko.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Koncovky en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zingen) — spievať</div><div class=\"kurss-example\">tragen (trágen) — niesť / nosiť</div><div class=\"kurss-example\">Garten (garten) — záhrada</div><div class=\"kurss-example\">Vogel (fógel) — vták</div><div class=\"kurss-example\">Segel (zégel) — plachta</div><div class=\"kurss-example\">Braten (bráten) — pečienka</div><div class=\"kurss-example\">Bogen (bógen) — oblúk / luk</div><div class=\"kurss-example\">Spiegel (špígel) — zrkadlo</div><div class=\"kurss-example\">Finger (finger) — prst</div><div class=\"kurss-example\">Halter (halter) — držiak</div><div class=\"kurss-example\">Arbeiter (arbajter) — robotník</div><div class=\"kurss-example\">Häuser (hojzer) — domy</div><div class=\"kurss-example\">wieder (víder) — znova</div><div class=\"kurss-example\">breiter (brajter) — širší</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Písmeno h ako znak dĺžky</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rámen) — rám</div><div class=\"kurss-example\">Ohr (ór) — ucho</div><div class=\"kurss-example\">Kohle (kóle) — uhlie</div><div class=\"kurss-example\">Zahl (cál) — číslo</div><div class=\"kurss-example\">ihn (ín) — jeho / ho</div><div class=\"kurss-example\">ihm (ím) — jemu / mu</div><div class=\"kurss-example\">Huhn (hún) — sliepka</div><div class=\"kurss-example\">nahm (nám) — vzal</div><div class=\"kurss-example\">nehmen (némen) — vziať / brať</div><div class=\"kurss-example\">Schuh (šú) — topánka</div></div>\n              <p>V niektorých slovách h predlžuje predchádzajúcu samohlásku. V takých prípadoch sa h zvyčajne nevyslovuje.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Koncovky s e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lampa</div><div class=\"kurss-example\">Hase (háze) — zajac</div><div class=\"kurss-example\">Knabe (knábe) — chlapec</div><div class=\"kurss-example\">Rabe (rábe) — havran</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dlhé i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dí) — člen „die“</div><div class=\"kurss-example\">diese (díze) — táto / tieto</div><div class=\"kurss-example\">wieder (víder) — znova</div><div class=\"kurss-example\">Fliege (flíge) — mucha</div><div class=\"kurss-example\">Ziege (cíge) — koza</div><div class=\"kurss-example\">Stiel (štíl) — stonka / rúčka</div><div class=\"kurss-example\">Dieb (díp) — zlodej</div><div class=\"kurss-example\">hier (hír) — tu</div></div>\n              <p>Dlhé i sa v nemčine často píše ako ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Zdvojené samohlásky</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zál) — sála</div><div class=\"kurss-example\">Saat (zát) — siatie / osivo</div><div class=\"kurss-example\">Staat (štát) — štát</div><div class=\"kurss-example\">Beere (bére) — bobuľa</div><div class=\"kurss-example\">See (zé) — jazero / more</div><div class=\"kurss-example\">Beet (bét) — záhon</div><div class=\"kurss-example\">Boot (bót) — čln</div><div class=\"kurss-example\">Moor (mór) — rašelinisko / močiar</div><div class=\"kurss-example\">Moos (mós) — mach</div></div>\n              <p>Zdvojené samohlásky sa zvyčajne vyslovujú dlho.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — stena</div><div class=\"kurss-example\">Wände (vende) — steny</div><div class=\"kurss-example\">Vater (fáter) — otec</div><div class=\"kurss-example\">Väter (féter) — otcovia</div><div class=\"kurss-example\">Schrank (šrank) — skriňa</div><div class=\"kurss-example\">Schränke (šrenke) — skrine</div><div class=\"kurss-example\">Bank (bank) — lavica / banka</div><div class=\"kurss-example\">Bänke (benke) — lavice</div><div class=\"kurss-example\">Tal (tál) — údolie</div><div class=\"kurss-example\">Täler (téler) — údolia</div></div>\n              <p>ä je prehláska od a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (róze) — ruža</div><div class=\"kurss-example\">Röschen (rősschen) — ružička</div><div class=\"kurss-example\">Ofen (ófen) — pec</div><div class=\"kurss-example\">Öfen (őfen) — pece</div><div class=\"kurss-example\">Rock (rok) — sukňa</div><div class=\"kurss-example\">Röcke (röke) — sukne</div></div>\n              <p>ö je prehláska od o.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (kurc) — krátky</div><div class=\"kurss-example\">kürzer (kürcer) — kratší</div><div class=\"kurss-example\">Kunst (kunst) — umenie</div><div class=\"kurss-example\">Künste (künste) — umenia</div><div class=\"kurss-example\">Mutter (muter) — matka</div><div class=\"kurss-example\">Mütter (müter) — matky</div></div>\n              <p>ü je prehláska od u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvojhlásky: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — strom</div><div class=\"kurss-example\">Bäume (bojme) — stromy</div><div class=\"kurss-example\">Haus (haus) — dom</div><div class=\"kurss-example\">Häuser (hojzer) — domy</div><div class=\"kurss-example\">Strauch (štrauch) — ker</div><div class=\"kurss-example\">Sträucher (štrojcher) — kry</div><div class=\"kurss-example\">Maus (maus) — myš</div><div class=\"kurss-example\">Mäuse (mojze) — myši</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvojhlásky: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (hojte) — dnes</div><div class=\"kurss-example\">Leute (lojte) — ľudia</div><div class=\"kurss-example\">neu (noj) — nový</div><div class=\"kurss-example\">neun (nojn) — deväť</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvojhlásky: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (majn) — môj</div><div class=\"kurss-example\">dein (dajn) — tvoj</div><div class=\"kurss-example\">sein (zajn) — jeho / byť</div><div class=\"kurss-example\">frei (fraj) — voľný / slobodný</div><div class=\"kurss-example\">arbeiten (arbajten) — pracovať</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Poznámky k výslovnosti z 2. lekcie</h4>\n              <ul class=\"kurss-summary-list\"><li>v slovách ich, nicht, rechnen, zeichnen sa „ch“ vyslovuje mäkko (podobne ako slovenské „ch“, ale mäkšie, s jazykom bližšie k „j“)</li><li>v slovách arbeiten a zeichnen sa „ei“ vyslovuje ako „aj“</li><li>„sp“ na začiatku slova sa vyslovuje ako „šp“</li><li>v slovese tun sa písmeno „u“ vyslovuje dlho</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Zhrnutie</h4>\n              <ul class=\"kurss-summary-list\"><li>jedna spoluhláska po samohláske → často dlhá samohláska</li><li>dve alebo viac spoluhlások → často krátka samohláska</li><li>h môže predĺžiť samohlásku</li><li>ie často označuje dlhé i</li><li>zdvojené samohlásky sú zvyčajne dlhé</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Spoluhlásky a spojenia písmen</h3>\n            <p class=\"kurss-lesson-intro\">V nemčine sa niektoré spoluhlásky a spojenia písmen vyslovujú inak, než sa píšu. V tejto lekcii sú najdôležitejšie príklady pre začiatočníkov.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Spoluhlásky</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (rát) — koleso</div><div class=\"kurss-example\">die Räder (réder) — kolesá</div><div class=\"kurss-example\">Bad (bát) — kúpeľ / kúpeľňa</div><div class=\"kurss-example\">Bäder (béder) — kúpele / kúpeľne</div></div>\n              <p>Na konci slova sa spoluhlásky často nevyslovujú tak, ako sa píšu.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>„ch“ sa môže vyslovovať mäkko alebo tvrdo. V niektorých slovách znie ako slovenské „ch“ (po e, i mäkšie, s jazykom bližšie k „j“), v iných sa blíži ku „k“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rechnen) — počítať</div><div class=\"kurss-example\">zeichnen (cajchnen) — kresliť</div><div class=\"kurss-example\">nicht (nicht) — nie</div><div class=\"kurss-example\">schlecht (šlecht) — zlý</div><div class=\"kurss-example\">mich (mich) — mňa / ma</div><div class=\"kurss-example\">dich (dich) — teba / ťa</div><div class=\"kurss-example\">Strauch (štrauch) — ker</div><div class=\"kurss-example\">noch (noch) — ešte</div><div class=\"kurss-example\">Nacht (nacht) — noc</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>„sch“ sa v nemčine vyslovuje ako slovenské „š“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (šúle) — škola</div><div class=\"kurss-example\">Schüler (šűler) — žiak</div><div class=\"kurss-example\">Schiff (šif) — loď</div><div class=\"kurss-example\">Schraube (šraube) — skrutka</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp a st na začiatku slova</h4>\n              <p>Na začiatku slova alebo slabiky sa „sp“ často vyslovuje ako „šp“ a „st“ ako „št“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (špílen) — hrať sa / hrať</div><div class=\"kurss-example\">Sprung (šprung) — skok</div><div class=\"kurss-example\">stehen (štéen) — stáť</div><div class=\"kurss-example\">Stall (štal) — maštaľ / chliev</div><div class=\"kurss-example\">Stand (štant) — stánok / stav</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>„qu“ sa v nemčine zvyčajne vyslovuje ako „kv“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvál) — muka / trápenie</div><div class=\"kurss-example\">Quartier (kvartír) — ubytovanie / štvrť</div><div class=\"kurss-example\">quer (kvér) — naprieč / priečne</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s a z</h4>\n              <p>Na začiatku slova „s“ často znie ako „z“. Písmeno „z“ v nemčine znie ako slovenské „c“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zágen) — povedať / hovoriť</div><div class=\"kurss-example\">singen (zingen) — spievať</div><div class=\"kurss-example\">Rose (róze) — ruža</div><div class=\"kurss-example\">Zahl (cál) — číslo</div><div class=\"kurss-example\">Zeit (cajt) — čas</div><div class=\"kurss-example\">Zink (cink) — zinok</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>V nemčine sa „v“ často vyslovuje ako „f“. V cudzích slovách často znie ako slovenské „v“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fáter) — otec</div><div class=\"kurss-example\">von (fon) — od / z</div><div class=\"kurss-example\">viel (fíl) — veľa</div><div class=\"kurss-example\">vier (fír) — štyri</div><div class=\"kurss-example\">Villa (vila) — vila</div><div class=\"kurss-example\">Klavier (klavír) — klavír</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x a y</h4>\n              <p>„x“ sa vyslovuje ako „ks“. „y“ sa v niektorých slovách vyslovuje ako „ü“ (ako „i“ so zaokrúhlenými perami).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (féliks) — Felix</div><div class=\"kurss-example\">Axt (akst) — sekera</div><div class=\"kurss-example\">Mystik (müstik) — mystika</div><div class=\"kurss-example\">Mythe (műte) — mýtus</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>„ß“ sa v nemčine vyslovuje ako „s“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (fús) — chodidlo / noha</div><div class=\"kurss-example\">Füße (fűse) — chodidlá / nohy</div><div class=\"kurss-example\">Grüße (grűse) — pozdravy</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Zhrnutie</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → š</li><li>sp / st na začiatku → šp / št</li><li>qu → kv</li><li>z → c</li><li>v často → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Základy slovies</h3>\n            <p class=\"kurss-lesson-intro\">Slovesá 1. lekcie a ich tvary (časovanie)</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Slovesá</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — prichádzať</div><div class=\"kurss-example\">gehen — ísť</div><div class=\"kurss-example\">stehen — stáť</div><div class=\"kurss-example\">singen — spievať</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — ja prichádzam</div><div class=\"kurss-example\">du kommst — ty prichádzaš</div><div class=\"kurss-example\">er kommt — on prichádza</div><div class=\"kurss-example\">sie kommt — ona prichádza</div><div class=\"kurss-example\">wir kommen — my prichádzame</div><div class=\"kurss-example\">ihr kommt — vy prichádzate</div><div class=\"kurss-example\">sie kommen — oni / ony prichádzajú</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — ja idem</div><div class=\"kurss-example\">du gehst — ty ideš</div><div class=\"kurss-example\">er geht — on ide</div><div class=\"kurss-example\">sie geht — ona ide</div><div class=\"kurss-example\">wir gehen — my ideme</div><div class=\"kurss-example\">ihr geht — vy idete</div><div class=\"kurss-example\">sie gehen — oni / ony idú</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — ja stojím</div><div class=\"kurss-example\">du stehst — ty stojíš</div><div class=\"kurss-example\">er steht — on stojí</div><div class=\"kurss-example\">sie steht — ona stojí</div><div class=\"kurss-example\">wir stehen — my stojíme</div><div class=\"kurss-example\">ihr steht — vy stojíte</div><div class=\"kurss-example\">sie stehen — oni / ony stoja</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — ja spievam</div><div class=\"kurss-example\">du singst — ty spievaš</div><div class=\"kurss-example\">er singt — on spieva</div><div class=\"kurss-example\">sie singt — ona spieva</div><div class=\"kurss-example\">wir singen — my spievame</div><div class=\"kurss-example\">ihr singt — vy spievate</div><div class=\"kurss-example\">sie singen — oni / ony spievajú</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Slovesá 2. lekcie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — hrať</div><div class=\"kurss-example\">arbeiten — pracovať</div><div class=\"kurss-example\">fragen — pýtať sa</div><div class=\"kurss-example\">antworten — odpovedať</div><div class=\"kurss-example\">rechnen — počítať</div><div class=\"kurss-example\">zeichnen — kresliť</div><div class=\"kurss-example\">tun — robiť</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — ja hrám</div><div class=\"kurss-example\">du spielst — ty hráš</div><div class=\"kurss-example\">er spielt — on hrá</div><div class=\"kurss-example\">sie spielt — ona hrá</div><div class=\"kurss-example\">wir spielen — my hráme</div><div class=\"kurss-example\">ihr spielt — vy hráte</div><div class=\"kurss-example\">sie spielen — oni / ony hrajú</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — ja pracujem</div><div class=\"kurss-example\">du arbeitest — ty pracuješ</div><div class=\"kurss-example\">er arbeitet — on pracuje</div><div class=\"kurss-example\">sie arbeitet — ona pracuje</div><div class=\"kurss-example\">wir arbeiten — my pracujeme</div><div class=\"kurss-example\">ihr arbeitet — vy pracujete</div><div class=\"kurss-example\">sie arbeiten — oni / ony pracujú</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — ja sa pýtam</div><div class=\"kurss-example\">du fragst — ty sa pýtaš</div><div class=\"kurss-example\">er fragt — on sa pýta</div><div class=\"kurss-example\">sie fragt — ona sa pýta</div><div class=\"kurss-example\">wir fragen — my sa pýtame</div><div class=\"kurss-example\">ihr fragt — vy sa pýtate</div><div class=\"kurss-example\">sie fragen — oni / ony sa pýtajú</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — ja odpovedám</div><div class=\"kurss-example\">du antwortest — ty odpovedáš</div><div class=\"kurss-example\">er antwortet — on odpovedá</div><div class=\"kurss-example\">sie antwortet — ona odpovedá</div><div class=\"kurss-example\">wir antworten — my odpovedáme</div><div class=\"kurss-example\">ihr antwortet — vy odpovedáte</div><div class=\"kurss-example\">sie antworten — oni / ony odpovedajú</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — ja počítam</div><div class=\"kurss-example\">du rechnest — ty počítaš</div><div class=\"kurss-example\">er rechnet — on počíta</div><div class=\"kurss-example\">sie rechnet — ona počíta</div><div class=\"kurss-example\">wir rechnen — my počítame</div><div class=\"kurss-example\">ihr rechnet — vy počítate</div><div class=\"kurss-example\">sie rechnen — oni / ony počítajú</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — ja kreslím</div><div class=\"kurss-example\">du zeichnest — ty kreslíš</div><div class=\"kurss-example\">er zeichnet — on kreslí</div><div class=\"kurss-example\">sie zeichnet — ona kreslí</div><div class=\"kurss-example\">wir zeichnen — my kreslíme</div><div class=\"kurss-example\">ihr zeichnet — vy kreslíte</div><div class=\"kurss-example\">sie zeichnen — oni / ony kreslia</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — ja robím</div><div class=\"kurss-example\">du tust — ty robíš</div><div class=\"kurss-example\">er tut — on robí</div><div class=\"kurss-example\">sie tut — ona robí</div><div class=\"kurss-example\">wir tun — my robíme</div><div class=\"kurss-example\">ihr tut — vy robíte</div><div class=\"kurss-example\">sie tun — oni / ony robia</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Stavba vety</h3>\n            <p class=\"kurss-lesson-intro\">V opytovacej vete stojí sloveso v nemčine zvyčajne na prvom mieste.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Príklady</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Ty prichádzaš.</div><div class=\"kurss-example\">Kommst du? — Prichádzaš?</div><div class=\"kurss-example\">Er singt. — On spieva.</div><div class=\"kurss-example\">Singt er? — Spieva?</div><div class=\"kurss-example\">Stehst du? — Stojíš?</div><div class=\"kurss-example\">Ja, ich stehe. — Áno, stojím.</div><div class=\"kurss-example\">Geht ihr? — Idete?</div><div class=\"kurss-example\">Ja, wir gehen. — Áno, ideme.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Otázky s „was“</h4>\n              <p>Ak sa otázka začína opytovacím slovom, sloveso v nemčine zvyčajne stojí hneď za opytovacím slovom.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Čo robíš?</div><div class=\"kurss-example\">Was tut er? — Čo robí on?</div><div class=\"kurss-example\">Was tut sie? — Čo robí ona?</div><div class=\"kurss-example\">Was tun sie? — Čo robia oni / ony?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Zápor s „nicht“</h4>\n              <p>Ak sa zápor „nicht“ vzťahuje na sloveso, v nemčine zvyčajne stojí za slovesom.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Nehrám sa.</div><div class=\"kurss-example\">Paul fragt nicht. — Pavol sa nepýta.</div><div class=\"kurss-example\">Er kommt nicht. — On neprichádza.</div><div class=\"kurss-example\">Sie singen nicht. — Oni / ony nespievajú.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vety z 2. hodiny</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Hráš sa?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Nie, nehrám sa, pracujem.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Pavol sa nepýta, pracuje.</div><div class=\"kurss-example\">Arbeitest du? — Pracuješ?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Nie, nepracujem, spievam.</div><div class=\"kurss-example\">Was tut Paul? — Čo robí Pavol?</div><div class=\"kurss-example\">Er spielt. — On sa hrá.</div><div class=\"kurss-example\">Was tut Marie? — Čo robí Mária?</div><div class=\"kurss-example\">Sie singt. — Ona spieva.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Pavol sa hrá, ale Mária spieva.</div><div class=\"kurss-example\">Singt ihr? — Spievate?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Nie, nespievame, pracujeme.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Čo robia Pavol a Mária?</div><div class=\"kurss-example\">Sie fragen. — Oni sa pýtajú.</div><div class=\"kurss-example\">Sie antworten nicht. — Oni neodpovedajú.</div><div class=\"kurss-example\">Wer arbeitet? — Kto pracuje?</div><div class=\"kurss-example\">Wir arbeiten. — My pracujeme.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Počítame a kreslíme.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Oni / ony prichádzajú, pýtajú sa, odpovedajú, pracujú, hrajú sa, spievajú a idú.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Lekcia 2</h3>\n            <p class=\"kurss-lesson-intro\">Druhá lekcia: dialógy, slová, výslovnosť, gramatika a prekladanie.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialógy / vety</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Slová</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — hrať sa; hrať</div>\n                  <div class=\"kurss-example\">nein — nie</div>\n                  <div class=\"kurss-example\">nicht — ne, nie</div>\n                  <div class=\"kurss-example\">arbeiten — pracovať</div>\n                  <div class=\"kurss-example\">fragen — pýtať sa</div>\n                  <div class=\"kurss-example\">was tut er? — čo robí on?</div>\n                  <div class=\"kurss-example\">was tun sie? — čo robia oni / ony?</div>\n                  <div class=\"kurss-example\">aber — ale</div>\n                  <div class=\"kurss-example\">antworten — odpovedať</div>\n                  <div class=\"kurss-example\">rechnen — počítať</div>\n                  <div class=\"kurss-example\">zeichnen — kresliť</div>\n                  <div class=\"kurss-example\">Marie — Mária</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Výslovnosť</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">V slovách ich, nicht, rechnen, zeichnen sa ch vyslovuje mäkko – približne ako slovenské ch, ale so stredom jazyka pri tvrdom podnebí, podobne ako pri j.</div><div class=\"kurss-example\">V slovách arbeiten, zeichnen sa dvojhláska ei vyslovuje približne ako slovenské aj.</div><div class=\"kurss-example\">Skupinu spoluhlások sp vyslovujeme ako šp: spielen (špílen).</div><div class=\"kurss-example\">V slovese tun sa u vyslovuje dlho vo všetkých osobách.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Koncovky s e</h4>\n                  <div class=\"lesson1-grammar-note\">Ak sa kmeň slovesa končí na t, d, chn, pri časovaní sa pred koncovky -st a -t vkladá e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Opytovacie slovo</h4>\n                  <div class=\"lesson1-grammar-note\">V opytovacích vetách, ktoré sa začínajú opytovacím slovom, napríklad: čo? kto? ktorý? prečo? načo? a pod., stojí sloveso hneď za opytovacím slovom.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Čo robíš?</div><div class=\"kurss-example\">Was tut er? — Čo robí on?</div><div class=\"kurss-example\">Was tut sie? — Čo robí ona?</div><div class=\"kurss-example\">Was tun sie? — Čo robia oni / ony?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Zápor s nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Ak sa zápor nicht vzťahuje na sloveso, stojí záporné slovo za slovesom.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — On neprichádza.</div><div class=\"kurss-example\">Sie singen nicht. — Oni nespievajú.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prelož</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcia 2: prekladová kartička\">\n                    <span class=\"lesson1-training-progress\">Lekcia 2 · Prelož: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Kto sa pýta?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Kliknutím na kartičku zobrazíš nemecký preklad. Po odpovedi ďalšie kliknutie zobrazí ďalšiu kartičku.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Lekcia 6</h3>\n    <p class=\"kurss-lesson-intro\">Číslovky, množné číslo, prehlásky a tvary množného čísla podstatných mien.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialógy / vety</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Slová</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — nachádza sa, je, leží</div><div class=\"kurss-example\">der Bleistift (blajštift) — ceruzka</div><div class=\"kurss-example\">einige (ajnige) — niekoľko</div><div class=\"kurss-example\">hinlegen — odložiť</div><div class=\"kurss-example\">legt hin — odloží</div><div class=\"kurss-example\">wieder (víder) — opäť</div><div class=\"kurss-example\">aufmachen — otvoriť</div><div class=\"kurss-example\">er macht auf — on otvorí</div><div class=\"kurss-example\">anspitzen (anšpicen) — zastrúhať</div><div class=\"kurss-example\">er spitzt an — on zastrúha</div><div class=\"kurss-example\">sich setzen — sadnúť si</div><div class=\"kurss-example\">setzt sich — sadne si</div><div class=\"kurss-example\">der Schlüssel (šlüsel) — kľúč</div><div class=\"kurss-example\">das Fenster (fenster) — okno</div><div class=\"kurss-example\">die Tafel (dí táfel) — tabuľa</div><div class=\"kurss-example\">der Garten — záhrada</div><div class=\"kurss-example\">der Löffel — lyžica</div><div class=\"kurss-example\">zählen (célen) — rátať</div><div class=\"kurss-example\">die Nadel — ihla</div><div class=\"kurss-example\">was ist das — čo je to?</div><div class=\"kurss-example\">der Hammer — kladivo</div><div class=\"kurss-example\">die Hämmer — kladivá</div><div class=\"kurss-example\">der Deckel (dér dekel) — pokrievka, veko</div><div class=\"kurss-example\">der Teller — tanier</div><div class=\"kurss-example\">der Wagen — voz</div><div class=\"kurss-example\">der Schlitten — sane, sánky</div><div class=\"kurss-example\">das Ding — vec</div><div class=\"kurss-example\">die Dinge — veci</div><div class=\"kurss-example\">wie sind die Dinge? — aké sú veci?</div><div class=\"kurss-example\">voll (fol) — plný</div><div class=\"kurss-example\">leer (lér) — prázdny</div><div class=\"kurss-example\">schwer (švér) — ťažký</div><div class=\"kurss-example\">leicht — ľahký</div><div class=\"kurss-example\">der Eimer — vedro</div><div class=\"kurss-example\">wieviel (vífíl) — koľko</div><div class=\"kurss-example\">wieviel Nadeln — koľko ihiel</div><div class=\"kurss-example\">hier (hír) — tu</div><div class=\"kurss-example\">dort — tam</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Výslovnosť</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä je prehláska samohlásky a a vyslovuje sa ako krátke alebo dlhé e.</div><div class=\"kurss-example\">Príklady: das Mädchen (métchen), die Bänke (dí benke), der Vater (dér fáter), die Väter (dí féter).</div><div class=\"kurss-example\">ü je prehláska samohlásky u. Pri jej vyslovovaní treba pery silno zaokrúhliť a so zaokrúhlenými perami sa pokúsiť vysloviť i.</div><div class=\"kurss-example\">Príklady: fünf, der Schlüssel (šlüsel).</div><div class=\"kurss-example\">ö sa vyslovuje so zaokrúhlenými perami, pričom sa snažíme vysloviť e: der Löffel.</div><div class=\"kurss-example\">Zdvojená samohláska označuje dlhú samohlásku: leer (lér).</div><div class=\"kurss-example\">Dvojhláska eu sa vyslovuje ako oj: neun (nojn).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramatika a vysvetlivky</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Prízvučná predpona zloženého slovesa sa v prítomnom čase oddeľuje od slovesa a stojí na konci vety.</div><div class=\"kurss-example\">Príklady: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Číslovka jeden má pri podstatnom mene tvar vo všetkých troch rodoch: v mužskom rode ein, v ženskom rode eine, v strednom rode ein.</div><div class=\"kurss-example\">Príklady: ein Schüler — jeden žiak; eine Schülerin — jedna žiačka; ein Kind — jedno dieťa.</div><div class=\"kurss-example\">Číslovky: eins, zwei, drei, vier (fír), fünf, sechs (zeks), sieben (zíben), acht, neun (nojn), zehn (cén).</div><div class=\"kurss-example\">Spona má v nemčine tvar jednotného a množného čísla: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Ukazovacie zámeno to sa v slovenčine v takýchto vetách nemení – to je…, to sú… – a aj v nemčine sa používa jediný tvar: das.</div><div class=\"kurss-example\">Príklady: to je kladivo — das ist ein Hammer; to je ihla — das ist eine Nadel; to sú kladivá — das sind Hämmer; to sú ihly — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — voz a der Schlitten — sane: slovo sane je v slovenčine pomnožné, ale v nemčine sa obe slová používajú v jednotnom aj v množnom čísle.</div><div class=\"kurss-example\">Podstatné mená mužského a stredného rodu s koncovkou -er, -el, -en v množnom čísle často nedostávajú koncovku.</div><div class=\"kurss-example\">Príklady: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Podstatné mená ženského rodu s koncovkou -el, -er dostávajú v množnom čísle -n.</div><div class=\"kurss-example\">Príklady: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Výnimky: die Mutter (matka) — die Mütter (matky); die Tochter (dcéra) — die Töchter (dcéry).</div><div class=\"kurss-example\">Neurčitý člen nemá množné číslo: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">V oznamovacej vete stojí slovesný prísudok na druhom mieste: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prelož</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcia 6: prekladová kartička\"><span class=\"lesson1-training-progress\">Lekcia 6 · Prelož: 1 / 21</span><span class=\"lesson1-training-text\">Paul berie ceruzku a kreslí.</span></button><p class=\"lesson1-training-hint\">Kliknutím na kartičku zobrazíš nemecký preklad. Po odpovedi ďalšie kliknutie zobrazí ďalšiu kartičku.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Lekcia 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akuzatív, sitzen, fragen a koncovka -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialógy / vety</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Slová</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zicen) — sedieť</div>\n        <div class=\"kurss-example\">fragen (frágen) — pýtať sa</div>\n        <div class=\"kurss-example\">der Lehrer (dér lérer) — učiteľ</div>\n        <div class=\"kurss-example\">gut (gút) — dobre</div>\n        <div class=\"kurss-example\">wen (vén) — koho</div>\n        <div class=\"kurss-example\">loben — chváliť</div>\n        <div class=\"kurss-example\">der Schüler (šüler) — žiak</div>\n        <div class=\"kurss-example\">klein — malý</div>\n        <div class=\"kurss-example\">groß (grós) — veľký</div>\n        <div class=\"kurss-example\">die Lehrerin — učiteľka</div>\n        <div class=\"kurss-example\">die Schülerin — žiačka</div>\n        <div class=\"kurss-example\">schlecht (šlecht) — zle</div>\n        <div class=\"kurss-example\">tadeln — karhať</div>\n        <div class=\"kurss-example\">oder (óder) — alebo</div>\n        <div class=\"kurss-example\">das Kind (kint) — dieťa</div>\n        <div class=\"kurss-example\">artig (ártich) — poslušný</div>\n        <div class=\"kurss-example\">die Mutter — matka</div>\n        <div class=\"kurss-example\">lieben (líben) — milovať</div>\n        <div class=\"kurss-example\">der Vater (fáter) — otec</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Výslovnosť</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz je zdvojené z a vyslovuje sa ako slovenské c: sitzen (zicen).</div>\n        <div class=\"kurss-example\">v sa v nemeckých slovách vyslovuje ako f: der Vater (fáter).</div>\n        <div class=\"kurss-example\">ß sa nazýva Eszett a vyslovuje sa ako slovenské s: groß (grós), weiß (vajs).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominatív a akuzatív</h4><div class=\"lesson1-grammar-note\">V slovenčine odpovedá nominatív na otázku kto? čo?, akuzatív na otázku koho? čo?</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">V nemčine je otázka v nominatíve wer? pre osoby a was? pre veci.</div><div class=\"kurss-example\">V akuzatíve je otázka wen? pre osoby a was? pre veci.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Zmena členov v akuzatíve</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + akuzatív</h4><div class=\"lesson1-grammar-note\">Sloveso fragen sa v nemčine viaže s akuzatívom.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Koncovka -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Mnoho podstatných mien ženského rodu sa tvorí koncovkou -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Miesto slovesa</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">V oznamovacej vete stojí sloveso na druhom mieste.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prelož</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcia 5: prekladová kartička\"><span class=\"lesson1-training-progress\">Lekcia 5 · Prelož: 1 / 16</span><span class=\"lesson1-training-text\">Koho miluje otec?</span></button><p class=\"lesson1-training-hint\">Kliknutím na kartičku zobrazíš nemecký preklad. Po odpovedi ďalšie kliknutie zobrazí ďalšiu kartičku.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Lekcia 4</h3>\n            <p class=\"kurss-lesson-intro\">Akuzatív, nehmen, hinlegen, hinausgehen a prídavné mená.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialógy / vety</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Slová</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (némen) — brať</div><div class=\"kurss-example\">er nimmt (nimt) — on berie</div><div class=\"kurss-example\">der Federhalter (dér féderhalter) — perodržiak</div><div class=\"kurss-example\">einen Federhalter — perodržiak</div><div class=\"kurss-example\">zeigen — ukazovať</div><div class=\"kurss-example\">schwarz (švarc) — čierny</div><div class=\"kurss-example\">weiß (vajs) — biely</div><div class=\"kurss-example\">die Feder (dí féder) — pero</div><div class=\"kurss-example\">eine Feder — pero</div><div class=\"kurss-example\">spitz (špic) — špicatý</div><div class=\"kurss-example\">hinlegen — odložiť</div><div class=\"kurss-example\">legt hin — odloží</div><div class=\"kurss-example\">das Mädchen (métchen) — dievča</div><div class=\"kurss-example\">das Messer — nôž</div><div class=\"kurss-example\">ein Messer — nôž</div><div class=\"kurss-example\">scharf — ostrý</div><div class=\"kurss-example\">stumpf (štumpf) — neostrý, tupý</div><div class=\"kurss-example\">dann — potom</div><div class=\"kurss-example\">hinaus — von</div><div class=\"kurss-example\">hinausgehen — vyjsť, ísť von</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Výslovnosť</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Koncovky -en, -er, -el sú neprízvučné, preto je e v týchto koncovkách počuť len slabo: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h môže byť v nemčine buď hláska, alebo znak dĺžky predchádzajúcej samohlásky.</div><div class=\"kurss-example\">Ak je h znakom dĺžky, nevyslovuje sa ako hláska: nehmen (némen).</div><div class=\"kurss-example\">Ak za samohláskou nasleduje iba jedna spoluhláska, samohláska sa vyslovuje dlho: die (dí) Feder (féder), den (dén).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akuzatív</h4><div class=\"lesson1-grammar-note\">V ženskom a strednom rode sa akuzatív zhoduje s nominatívom. Mení sa iba mužský rod.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Zámená</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — mužský rod</div><div class=\"kurss-example\">sie — ženský rod</div><div class=\"kurss-example\">es — stredný rod</div><div class=\"kurss-example\">v množnom čísle — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Odlučiteľné slovesá</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Prídavné mená</h4><div class=\"lesson1-grammar-note\">Ak je prídavné meno vo vete súčasťou prísudku, nemení sa ani v rode, ani v čísle.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Zápor s nicht</h4><div class=\"lesson1-grammar-note\">Ak nicht popiera prídavné meno, stojí pred popieraným slovom.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Podstatné mená s príponou -chen a -lein sú stredného rodu: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prelož</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcia 4: prekladová kartička\"><span class=\"lesson1-training-progress\">Lekcia 4 · Prelož: 1 / 16</span><span class=\"lesson1-training-text\">Dievča berie perodržiak.</span></button><p class=\"lesson1-training-hint\">Kliknutím na kartičku zobrazíš nemecký preklad. Po odpovedi ďalšie kliknutie zobrazí ďalšiu kartičku.</p></div></div></details>",
  "kurssLesson3": "            <h3>Lekcia 3</h3>\n            <p class=\"kurss-lesson-intro\">Tretia lekcia: dialógy, slová, výslovnosť, gramatika a prekladanie.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialógy / vety</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Slová</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — kto</div><div class=\"kurss-example\">was — čo</div><div class=\"kurss-example\">hier — tu</div><div class=\"kurss-example\">dort — tam</div><div class=\"kurss-example\">der Tisch — stôl</div><div class=\"kurss-example\">ein Tisch — stôl</div><div class=\"kurss-example\">die Bank — lavica</div><div class=\"kurss-example\">eine Bank — lavica</div><div class=\"kurss-example\">liegen — ležať</div><div class=\"kurss-example\">liegt hier ein Buch? — je / leží tu kniha?</div><div class=\"kurss-example\">das Buch — kniha</div><div class=\"kurss-example\">ein Buch — kniha</div><div class=\"kurss-example\">hängen — visieť</div><div class=\"kurss-example\">das Bild — obraz</div><div class=\"kurss-example\">ein Bild — obraz</div><div class=\"kurss-example\">die Tafel — tabuľa</div><div class=\"kurss-example\">eine Tafel — tabuľa</div><div class=\"kurss-example\">wie — aký, aká</div><div class=\"kurss-example\">ist — je</div><div class=\"kurss-example\">dick — hrubý, tučný</div><div class=\"kurss-example\">das Heft — zošit</div><div class=\"kurss-example\">ein Heft — zošit</div><div class=\"kurss-example\">dünn — tenký, chudý</div><div class=\"kurss-example\">niedrig — nízky</div><div class=\"kurss-example\">hoch — vysoký</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Výslovnosť</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Dlhé í sa v nemčine označuje ako ie: liegen (lígen), hier (hír), wie (ví).</div><div class=\"kurss-example\">ck je zdvojené k: dick (dikk).</div><div class=\"kurss-example\">V prídavných menách a príslovkách znie koncovka -ig ako mäkké -ich: niedrig (nídrich).</div><div class=\"kurss-example\">Ak za koncovkou -ig nasleduje e: -ige, g sa vyslovuje ako jasné g: niedrige (nídrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Podmet</h4><div class=\"lesson1-grammar-note\">Podmet v nemčine odpovedá na otázku wer? / was? a stojí v nominatíve.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Otázkou wer? sa pýtame na osoby.</div><div class=\"kurss-example\">Otázkou was? sa pýtame na veci.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Členy</h4><div class=\"lesson1-grammar-note\">V nemčine majú podstatné mená 3 rody: mužský, ženský a stredný. Pred podstatným menom zvyčajne stojí slovíčko, ktoré sa nazýva člen. Toto slovíčko sa neprekladá.</div><h5 class=\"lesson2-subtitle\">Určitý člen</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">mužský rod — der</div><div class=\"kurss-example\">ženský rod — die</div><div class=\"kurss-example\">stredný rod — das</div><div class=\"kurss-example\">V množnom čísle je určitý člen pre všetky tri rody die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Neurčitý člen</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">mužský rod — ein</div><div class=\"kurss-example\">ženský rod — eine</div><div class=\"kurss-example\">stredný rod — ein</div><div class=\"kurss-example\">Neurčitý člen nemá množné číslo.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Vlastné mená</h4><div class=\"lesson1-grammar-note\">Pred vlastnými menami sa člen nepoužíva.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Miesto slovesa</h4><div class=\"lesson1-grammar-note\">V oznamovacej vete stojí sloveso na druhom mieste.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">O predmetoch vo zvislej polohe sa po nemecky hovorí, že stoja:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">O predmetoch vo vodorovnej polohe sa hovorí, že ležia:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Predmety môžu aj visieť:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prelož</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcia 3: prekladová kartička\"><span class=\"lesson1-training-progress\">Lekcia 3 · Prelož: 1 / 22</span><span class=\"lesson1-training-text\">Počítaš?</span></button><p class=\"lesson1-training-hint\">Kliknutím na kartičku zobrazíš nemecký preklad. Po odpovedi ďalšie kliknutie zobrazí ďalšiu kartičku.</p></div></div></details>",
  "kurssLesson7": "            <h3>Lekcia 7</h3>\n            <p class=\"kurss-lesson-intro\">Siedma lekcia: rozkazovací spôsob, zdvorilé oslovenie a množné číslo.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialógy / vety</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Slová</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — spievať</div><div class=\"kurss-example\">singe — spievaj</div><div class=\"kurss-example\">singt — spievajte</div><div class=\"kurss-example\">singen Sie — spievajte</div><div class=\"kurss-example\">das Lied (das lít) — pieseň</div><div class=\"kurss-example\">Sie — Vy</div><div class=\"kurss-example\">zählen — rátať</div><div class=\"kurss-example\">das Fräulein (frojlajn) — slečna</div><div class=\"kurss-example\">der Müller — mlynár</div><div class=\"kurss-example\">öffnen — otvoriť</div><div class=\"kurss-example\">das Fenster (fenster) — okno</div><div class=\"kurss-example\">alle — všetci</div><div class=\"kurss-example\">der Spiegel (špígel) — zrkadlo</div><div class=\"kurss-example\">der Lappen — handra, utierka</div><div class=\"kurss-example\">der Spaten — rýľ</div><div class=\"kurss-example\">der Besen — metla</div><div class=\"kurss-example\">die Schaufel — lopatka</div><div class=\"kurss-example\">die Schüssel — misa</div><div class=\"kurss-example\">das Zimmer — izba</div><div class=\"kurss-example\">das Ufer (úfer) — breh</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Výslovnosť</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp sa na začiatku slova alebo slabiky vyslovuje ako šp: der Spiegel (dér špígel).</div><div class=\"kurss-example\">sch sa vyslovuje ako slovenské š: die Schaufel (dí šaufel), die Schüssel (dí šüsel).</div><div class=\"kurss-example\">Dvojhláska äu sa vyslovuje ako slovenské oj: das Fräulein (das frojlajn).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Rozkazovací spôsob</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Rozkazovací spôsob v 2. osobe jednotného čísla zodpovedá 2. osobe jednotného čísla slovesa bez osobnej koncovky -st, pričom sa pridáva koncovka -e.</div><div class=\"kurss-example\">Príklady: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Veľmi často sa koncovka -e vynecháva, ak je rozkazovací tvar jednoslabičný: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Rozkazovací spôsob v množnom čísle</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Rozkazovací tvar 2. osoby množného čísla sa zhoduje s 2. osobou množného čísla prítomného času, ale používa sa bez zámena.</div><div class=\"kurss-example\">Príklady: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Zdvorilé oslovenie so Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Zdvorilé oslovenie „Vy“ sa zhoduje s 3. osobou množného čísla. Zámeno Sie sa píše s veľkým začiatočným písmenom a stojí za slovesom.</div><div class=\"kurss-example\">Príklady: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Sloveso öffnen kvôli ľahšej výslovnosti vkladá v 2. a 3. osobe jednotného čísla a v 2. osobe množného čísla medzi kmeň a koncovku e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Cvičenie</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcia 7: kartička na cvičenie\"><span class=\"lesson1-training-progress\">Lekcia 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — pýtať sa</span></button><p class=\"lesson1-training-hint\">Ťukni na kartičku a zobrazia sa rozkazovacie tvary.</p></div></div></details>",
  "kurssLesson1": "            <h3>Lekcia 1</h3>\n            <p class=\"kurss-lesson-intro\">Prvá lekcia: slovesá v prítomnom čase, slovíčka, výslovnosť, gramatika a prekladanie.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Slovesá v prítomnom čase</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Slovesá a ich časovanie v prítomnom čase.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — prichádzať</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>ja prichádzam</span><span>du</span><strong>kommst</strong><span>ty prichádzaš</span><span>er / sie</span><strong>kommt</strong><span>on / ona prichádza</span><span>wir</span><strong>kommen</strong><span>my prichádzame</span><span>ihr</span><strong>kommt</strong><span>vy prichádzate</span><span>sie / Sie</span><strong>kommen</strong><span>oni prichádzajú / Vy prichádzate</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — ísť</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>ja idem</span><span>du</span><strong>gehst</strong><span>ty ideš</span><span>er / sie</span><strong>geht</strong><span>on / ona ide</span><span>wir</span><strong>gehen</strong><span>my ideme</span><span>ihr</span><strong>geht</strong><span>vy idete</span><span>sie / Sie</span><strong>gehen</strong><span>oni idú / Vy idete</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — stáť</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>ja stojím</span><span>du</span><strong>stehst</strong><span>ty stojíš</span><span>er / sie</span><strong>steht</strong><span>on / ona stojí</span><span>wir</span><strong>stehen</strong><span>my stojíme</span><span>ihr</span><strong>steht</strong><span>vy stojíte</span><span>sie / Sie</span><strong>stehen</strong><span>oni stoja / Vy stojíte</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — spievať</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>ja spievam</span><span>du</span><strong>singst</strong><span>ty spievaš</span><span>er / sie</span><strong>singt</strong><span>on / ona spieva</span><span>wir</span><strong>singen</strong><span>my spievame</span><span>ihr</span><strong>singt</strong><span>vy spievate</span><span>sie / Sie</span><strong>singen</strong><span>oni spievajú / Vy spievate</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Príklady</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Slovíčka</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Približná výslovnosť slov je uvedená v zátvorkách slovenskými písmenami.<br>Platí to aj v ďalších lekciách.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vír) — my</div><div class=\"kurss-example\">V slove „wir“ sa i vyslovuje dlho.</div><div class=\"kurss-example\">kommen (komen) — prichádzať</div><div class=\"kurss-example\">gehen (gé-en) — ísť</div><div class=\"kurss-example\">stehen (šté-en) — stáť</div><div class=\"kurss-example\">singen (zingen) — spievať</div><div class=\"kurss-example\">du (dú) kommst — ty prichádzaš</div><div class=\"kurss-example\">er (ér) kommt — on prichádza</div><div class=\"kurss-example\">sie (zí) kommt — ona prichádza</div><div class=\"kurss-example\">wer (vér) — kto?</div><div class=\"kurss-example\">ja (já) — áno</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Výslovnosť</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Správna výslovnosť slov, zapísaná slovenskými písmenami, je uvedená v lekciách.</div><div class=\"kurss-example\">Wir (vír) — my. V slove wir sa í vyslovuje vždy dlho.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitív</h4><div class=\"lesson1-grammar-note\">Základný tvar slovesa. Infinitív sa zvyčajne končí na -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Koncovky prítomného času</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Odstráň <span class=\"lesson1-ending-accent\">-en</span> zo základného tvaru slovesa a pridaj koncovku.</strong></p><p>Príklad: kommen → komm + koncovka</p><div class=\"lesson1-ending-process\" aria-label=\"Postup tvorenia tvarov prítomného času\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>základný tvar</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>odstráň <span class=\"lesson1-ending-accent\">-en</span></strong><span>zostane kmeň</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>kmeň</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>pridaj koncovku</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Príklady</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Opytovacie vety</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>V nemeckej opytovacej vete sa sloveso zvyčajne presúva na prvé miesto.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">V slovenčine:<br>Ty prichádzaš.<br>Prichádzaš?</div><div class=\"kurss-example\">V nemčine:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — ty prichádzaš<br>kommst du? — prichádzaš?</div><div class=\"kurss-example\">er singt — on spieva<br>singt er? — spieva on?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Rozlišovanie osôb</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — on prichádza</div><div class=\"kurss-example\">sie kommt — ona prichádza</div><div class=\"kurss-example\">sie kommen — oni / ony prichádzajú</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prelož</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcia 1: tréningová kartička\">\n                    <span class=\"lesson1-training-progress\">Lekcia 1 · Prelož: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Prichádzaš?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Kliknutím na kartičku zobrazíš nemecký preklad. Po odpovedi ďalšie kliknutie zobrazí ďalšiu kartičku.</p>\n                </div>\n              </div>\n            </details>"
};

